import openpyxl
import json

# Extract all line items from Income Statements
def extract_income(filepath, label):
    wb = openpyxl.load_workbook(filepath)
    ws = wb.active
    data = {}
    for row in ws.iter_rows(min_row=2, values_only=True):
        if row[0] and row[1] is not None:
            data[row[0]] = row[1]
    print(f"\n{label} Income Statement (all line items):")
    for k, v in data.items():
        print(f"  {k}: {v:,.0f}")
    return data

def extract_bs(filepath, label):
    wb = openpyxl.load_workbook(filepath)
    ws = wb.active
    headers = [row[0] for row in ws.iter_rows(min_row=1, max_row=1, values_only=True)][0]
    data = {}
    for row in ws.iter_rows(min_row=2, values_only=True):
        if row[0]:
            data[row[0]] = {}
            for i, h in enumerate(headers):
                if row[i+1] is not None:
                    data[row[0]][str(h)] = row[i+1]
    print(f"\n{label} Balance Sheet:")
    for k, v in data.items():
        print(f"  {k}: {v}")
    return data

def extract_cf(filepath, label):
    wb = openpyxl.load_workbook(filepath)
    ws = wb.active
    data = {}
    for row in ws.iter_rows(min_row=2, values_only=True):
        if row[0] and row[1] is not None:
            data[row[0]] = row[1]
    print(f"\n{label} Cash Flow Statement (all line items):")
    for k, v in data.items():
        print(f"  {k}: {v:,.0f}")
    return data

dis_income = extract_income('/home/agent/workspace/DIS-US Income Statement (TTM).xlsx', 'DIS')
wbd_income = extract_income('/home/agent/workspace/WBD-US Income Statement (TTM).xlsx', 'WBD')
dis_bs = extract_bs('/home/agent/workspace/DIS-US Balance Sheet (Annual).xlsx', 'DIS')
wbd_bs = extract_bs('/home/agent/workspace/WBD-US Balance Sheet (Annual).xlsx', 'WBD')
dis_cf = extract_cf('/home/agent/workspace/DIS-US Cash Flow Statement (Annual).xlsx', 'DIS')
wbd_cf = extract_cf('/home/agent/workspace/WBD-US Cash Flow Statement (Annual).xlsx', 'WBD')

# Save all data
all_data = {
    'dis_income': dis_income,
    'wbd_income': wbd_income,
    'dis_bs': dis_bs,
    'wbd_bs': wbd_bs,
    'dis_cf': dis_cf,
    'wbd_cf': wbd_cf,
}

with open('/tmp/all_financial_data.json', 'w') as f:
    json.dump(all_data, f, default=str)

print("\n\nAll financial data saved to /tmp/all_financial_data.json")
