python3 << 'EOF'
import openpyxl
import json

# Extract Balance Sheets properly
def extract_bs(filepath, label):
    wb = openpyxl.load_workbook(filepath)
    ws = wb.active
    # Get headers from first row
    headers = []
    for cell in ws[1]:
        headers.append(cell.value)

    data = {}
    for row in ws.iter_rows(min_row=2, values_only=True):
        if row[0]:
            data[row[0]] = {}
            for i, h in enumerate(headers):
                if row[i+1] is not None:
                    data[row[0]][str(h)] = row[i+1]
    return data, headers

dis_bs, dis_bs_headers = extract_bs('/home/agent/workspace/DIS-US Balance Sheet (Annual).xlsx', 'DIS')
wbd_bs, wbd_bs_headers = extract_bs('/home/agent/workspace/WBD-US Balance Sheet (Annual).xlsx', 'WBD')

print("DIS Balance Sheet Headers:", dis_bs_headers)
print("\nWBD Balance Sheet Headers:", wbd_bs_headers)

print("\n\nDIS Balance Sheet (all line items):")
for k, v in dis_bs.items():
    print(f"  {k}: {v}")

print("\n\nWBD Balance Sheet (all line items):")
for k, v in wbd_bs.items():
    print(f"  {k}: {v}")

# Save
all_data = {
    'dis_bs': dis_bs,
    'dis_bs_headers': dis_bs_headers,
    'wbd_bs': wbd_bs,
    'wbd_bs_headers': wbd_bs_headers,
}

with open('/tmp/all_financial_data.json', 'w') as f:
    json.dump(all_data, f, default=str)

print("\n\nBalance sheet data saved")
EOF
